// Search seeds: category × city. Edit this list to control discovery scope.
// Each daily run will pick a rotating subset to spread quota and avoid hammering one query.
const seeds = [
  { category: 'barber',      query: 'barber shop',           city: 'Atlanta, GA' },
  { category: 'barber',      query: 'barber shop',           city: 'Houston, TX' },
  { category: 'hair_salon',  query: 'hair salon',            city: 'Phoenix, AZ' },
  { category: 'nail_salon',  query: 'nail salon',            city: 'Miami, FL' },
  { category: 'med_spa',     query: 'med spa',               city: 'Dallas, TX' },
  { category: 'realtor',     query: 'real estate agent',     city: 'Austin, TX' },
  { category: 'plumber',     query: 'plumber',               city: 'Charlotte, NC' },
  { category: 'home_service',query: 'hvac contractor',       city: 'Tampa, FL' },
  { category: 'restaurant',  query: 'family restaurant',     city: 'Nashville, TN' },
  { category: 'barber',      query: 'barber shop',           city: 'Las Vegas, NV' },
  { category: 'nail_salon',  query: 'nail salon',            city: 'Denver, CO' },
  { category: 'med_spa',     query: 'med spa',               city: 'San Diego, CA' }
];

// Rotate: pick 3 seeds per run, advancing daily so we cover all seeds across days.
const dayIndex = Math.floor(Date.now() / (1000 * 60 * 60 * 24));
const BATCH_SIZE = 3;
const start = (dayIndex * BATCH_SIZE) % seeds.length;
const todaysSeeds = [];
for (let i = 0; i < BATCH_SIZE; i++) {
  todaysSeeds.push(seeds[(start + i) % seeds.length]);
}

return todaysSeeds.map(s => ({ json: s }));

// Tag each scraped item with the seed's category and source, then split the array.
const seed = $('Build Search Seeds').item.json;
const items = $input.first().json;
const arr = Array.isArray(items) ? items : (items?.data || []);

return arr.map(place => ({
  json: {
    source: 'google_maps',
    category: seed.category,
    search_city: seed.city,
    raw: place
  }
}));

// Normalize Apify Google Maps payload into the canonical lead schema.
// Reference field names from compass/crawler-google-places dataset items.
const inputs = $input.all();
const out = [];

for (const item of inputs) {
  const r = item.json.raw || {};

  // Extract phone — Apify returns `phone` or `phoneUnformatted`.
  const phone = r.phoneUnformatted || r.phone || null;

  // Extract email if scrapeContacts was on — comes back in `emails` array.
  const email = Array.isArray(r.emails) && r.emails.length ? r.emails[0] : null;

  // Booking method heuristic from website + categories + title.
  const website = r.website || null;
  const title = (r.title || '').toLowerCase();
  const categoriesArr = (r.categories || []).map(c => (c || '').toLowerCase());

  // Canonical lead object.
  const lead = {
    lead_id: `${item.json.source}_${r.placeId || r.fid || crypto.randomUUID()}`,
    timestamp_discovered: new Date().toISOString(),
    source: item.json.source,
    category: item.json.category,
    business_name: r.title || null,
    website,
    phone,
    email,
    address: r.address || null,
    city: r.city || item.json.search_city.split(',')[0].trim(),
    state: r.state || (item.json.search_city.split(',')[1] || '').trim(),
    postal_code: r.postalCode || null,
    latitude: r.location?.lat ?? null,
    longitude: r.location?.lng ?? null,
    rating: r.totalScore ?? null,
    reviews_count: r.reviewsCount ?? null,
    google_maps_url: r.url || null,
    place_id: r.placeId || null,
    categories_detected: categoriesArr,
    permanently_closed: !!r.permanentlyClosed,
    temporarily_closed: !!r.temporarilyClosed,
    opening_hours: r.openingHours || null,
    // Raw scraped subset retained for the AI qualification stage:
    description: r.description || null,
    additional_info: r.additionalInfo || null
  };

  // Skip dead listings.
  if (lead.permanently_closed) continue;
  if (!lead.business_name) continue;

  out.push({ json: lead });
}

return out;

// Detect booking-tool tech stack from website HTML.
// Strong signal: if they already use Calendly/Square/Booksy/Vagaro, they understand automation —
// pitch is integration, not greenfield. If they use NONE, that's the cold opportunity.
const html = ($input.first().json.body || $input.first().json.data || '').toString().toLowerCase();
const lead = $('IF New Lead').item.json;

const signals = {
  has_calendly:    /calendly\.com/.test(html),
  has_square:      /squareup\.com|square\.site|squarespace-scheduling|acuityscheduling/.test(html),
  has_booksy:      /booksy\.com/.test(html),
  has_vagaro:      /vagaro\.com/.test(html),
  has_setmore:     /setmore\.com/.test(html),
  has_schedulicity:/schedulicity\.com/.test(html),
  has_mindbody:    /mindbodyonline\.com|mindbody\.io/.test(html),
  has_opentable:   /opentable\.com/.test(html),
  has_resy:        /resy\.com/.test(html),
  has_whatsapp_link:/wa\.me\/|api\.whatsapp\.com/.test(html),
  has_chatbot_widget:/intercom|drift\.com|tidio|tawk\.to|crisp\.chat|hubspot.*chat/.test(html),
  mentions_dm_to_book: /dm\s+to\s+book|message\s+to\s+book|dm\s+for\s+appointment/.test(html),
  mentions_call_to_book: /call\s+to\s+book|call\s+for\s+appointment|call\s+to\s+schedule/.test(html),
  has_contact_form: /<form[^>]*>/.test(html),
  has_phone_link:   /href="tel:/.test(html)
};

const booking_tools_detected = Object.entries(signals)
  .filter(([k, v]) => v && k.startsWith('has_') && k !== 'has_phone_link' && k !== 'has_contact_form' && k !== 'has_whatsapp_link' && k !== 'has_chatbot_widget')
  .map(([k]) => k.replace('has_', ''));

// Booking method heuristic.
let booking_method_detected = 'unknown';
if (booking_tools_detected.length > 0) booking_method_detected = 'link';
else if (signals.has_contact_form) booking_method_detected = 'form';
else if (signals.mentions_call_to_book && !signals.has_contact_form) booking_method_detected = 'call';
else if (signals.mentions_dm_to_book) booking_method_detected = 'dm';

return [{
  json: {
    ...lead,
    website_signals: signals,
    booking_tools_detected,
    booking_method_detected,
    website_fetch_status: $input.first().json.statusCode || null
  }
}];

// Parse Anthropic response, compute deterministic lead_score from sub-scores.
// We let the LLM extract evidence; the final 1–10 score is computed in code
// for consistency across runs.
const lead = $('Website Tech Detect').item.json;
const resp = $input.first().json;

// Anthropic returns { content: [{ type: 'text', text: '...' }, ...] }
let aiText = '';
try {
  aiText = (resp.content || []).filter(c => c.type === 'text').map(c => c.text).join('').trim();
} catch (e) {
  aiText = '';
}

// Strip accidental markdown fences if any.
aiText = aiText.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();

let ai = null;
try {
  ai = JSON.parse(aiText);
} catch (e) {
  // Salvage: find first { ... } block.
  const m = aiText.match(/\{[\s\S]*\}/);
  if (m) { try { ai = JSON.parse(m[0]); } catch (_) {} }
}

// Fallback if AI failed.
if (!ai) {
  return [{
    json: {
      ...lead,
      timestamp_qualified: new Date().toISOString(),
      lead_score: 0,
      classification: 'LOW',
      confidence: 0,
      pain_points: [],
      ai_insight_summary: 'AI qualification failed to return parseable JSON.',
      suggested_outreach_angle: '',
      signals_detected: [],
      ai_raw_response: aiText.slice(0, 500),
      qualification_failed: true,
      notified: false,
      status: 'new'
    }
  }];
}

const safe = (v, d = 0) => (typeof v === 'number' && !Number.isNaN(v)) ? v : d;

const booking_friction       = safe(ai.booking_friction?.score);
const manual_dependency      = safe(ai.manual_communication_dependency?.score);
const engagement             = safe(ai.engagement_quality?.score);
const activity               = safe(ai.activity_level?.score);
const automation_gap_count   = Array.isArray(ai.automation_gap_signals) ? ai.automation_gap_signals.length : 0;
const automation_gap_score   = Math.min(10, automation_gap_count * 2.5);

// Deterministic weighted score.
const raw_score =
  booking_friction      * 0.35 +
  manual_dependency     * 0.25 +
  automation_gap_score  * 0.20 +
  activity              * 0.15 +
  engagement            * 0.05;

// Apply confidence multiplier — uncertain qualifications get pulled toward the middle.
const confidence = Math.max(0, Math.min(1, safe(ai.overall_fit_confidence, 0.5)));
const confidence_adjusted = raw_score * (0.6 + 0.4 * confidence);

const lead_score = Math.round(Math.max(1, Math.min(10, confidence_adjusted)));

const HIGH = $('Set Config').item.json.HIGH_SCORE_THRESHOLD;
const MED  = $('Set Config').item.json.MEDIUM_SCORE_THRESHOLD;

let classification = 'LOW';
if (lead_score >= HIGH) classification = 'HIGH';
else if (lead_score >= MED) classification = 'MEDIUM';

const signals_detected = [
  ...(ai.automation_gap_signals || []),
  ...Object.entries(lead.website_signals || {}).filter(([k, v]) => v).map(([k]) => `website:${k}`)
];

return [{
  json: {
    ...lead,
    timestamp_qualified: new Date().toISOString(),
    lead_score,
    classification,
    confidence,
    pain_points: ai.pain_points || [],
    ai_insight_summary: `Booking friction ${booking_friction}/10. Manual dependency ${manual_dependency}/10. Automation gaps: ${automation_gap_count}.`,
    suggested_outreach_angle: ai.suggested_outreach_angle || '',
    signals_detected,
    ai_uncertainties: ai.uncertainties || [],
    qualification_failed: false,
    notified: false,
    status: 'new'
  }
}];

