// Error handler: log Apify failures into a 'failures' tab for later review.
const err = $input.first().json;
return [{
  json: {
    timestamp: new Date().toISOString(),
    stage: 'apify_gmaps',
    error_message: err?.error?.message || err?.message || 'unknown error',
    error_code: err?.error?.statusCode || err?.statusCode || null,
    seed_query: $('Build Search Seeds').item?.json?.query || null,
    seed_city: $('Build Search Seeds').item?.json?.city || null
  }
}];

// Handle AI qualification failures the same way — log and skip.
const err = $input.first().json;
const lead = $('Website Tech Detect').item?.json || {};
return [{
  json: {
    timestamp: new Date().toISOString(),
    stage: 'anthropic_qualify',
    error_message: err?.error?.message || err?.message || 'unknown error',
    error_code: err?.error?.statusCode || err?.statusCode || null,
    lead_id: lead.lead_id || null,
    business_name: lead.business_name || null
  }
}];
